# AUTOGENERATED! DO NOT EDIT!

from pathlib import Path
import asyncio

from ..config import get_config
from .._models import get_boxyard_meta, BoxPart
from .._remote_index import find_remote_box_by_id
from .._enums import StorageFormat
from .._models import BoxMeta
from .._utils.rclone import rclone_copy, rclone_copyto

async def copy_from_remote(
    config_path: Path,
    box_index_name: str,
    dest_path: Path,
    copy_meta: bool = False,
    copy_conf: bool = False,
    overwrite: bool = False,
    show_rclone_progress: bool = False,
    verbose: bool = False,
) -> Path:
    """
    Copy a remote box's data to a local path without including it in boxyard.

    This command downloads the box data to any local path without:
    - Adding it to boxyard tracking
    - Creating sync records
    - Making it an "included" box

    Args:
        config_path: Path to the boxyard config file
        box_index_name: The index name of the box (local)
        dest_path: Destination path for the copy
        copy_meta: Also copy boxmeta.toml
        copy_conf: Also copy conf/ folder
        overwrite: Overwrite if dest exists
        show_rclone_progress: Show rclone progress output
        verbose: Print verbose output

    Returns:
        The destination path
    """
    config = get_config(config_path)
    boxyard_meta = get_boxyard_meta(config)
    
    if box_index_name not in boxyard_meta.by_index_name:
        raise ValueError(f"Box '{box_index_name}' does not exist locally.")
    
    box_meta = boxyard_meta.by_index_name[box_index_name]
    dest_path = Path(dest_path).resolve()
    boxyard_data_path = config.boxyard_data_path.resolve()
    
    try:
        dest_path.relative_to(boxyard_data_path)
        raise ValueError(
            f"Destination path '{dest_path}' is within the boxyard data path '{boxyard_data_path}'. "
            f"This operation is not allowed to prevent conflicts with managed storage. "
            f"Use a path outside of '{boxyard_data_path}'."
        )
    except ValueError as e:
        if "is within the boxyard data path" in str(e):
            raise
        # Good - dest_path is not within boxyard_data_path
        pass
    
    # Also reject every configured checkout root. ``copy`` is deliberately
    # untracked; placing its destination under any checkout root would create an
    # ambiguous duplicate that looks like an included box.
    for _root_name, _root in config.configured_checkout_roots.items():
        _checkout_path = _root.path.resolve(strict=False)
        try:
            dest_path.relative_to(_checkout_path)
        except ValueError:
            continue
        raise ValueError(
            f"Destination path '{dest_path}' is within checkout root "
            f"'{_root_name}' at '{_checkout_path}'. Use a path outside all checkout roots."
        )
        pass
    if dest_path.exists() and not overwrite:
        raise ValueError(
            f"Destination path '{dest_path}' already exists. "
            f"Use --overwrite to overwrite existing files."
        )
    storage_location = box_meta.storage_location
    sl_config = config.storage_locations[storage_location]
    
    # Find remote index name by box_id (handles renames)
    remote_index_name = await find_remote_box_by_id(
        config=config,
        storage_location=storage_location,
        box_id=box_meta.box_id,
    )
    
    if remote_index_name is None:
        raise ValueError(
            f"Box '{box_index_name}' not found on remote storage '{storage_location}'. "
            f"The box may have been deleted or the remote is not accessible."
        )
    
    if verbose:
        print(f"Found remote box: {remote_index_name}")
    from boxyard import const
    
    remote_box_path = sl_config.store_path / const.REMOTE_BOXES_REL_PATH / remote_index_name
    remote_data_path = remote_box_path / const.BOX_DATA_REL_PATH
    remote_meta_path = remote_box_path / const.BOX_METAFILE_REL_PATH
    remote_conf_path = remote_box_path / const.BOX_CONF_REL_PATH
    # Create dest directory
    dest_path.mkdir(parents=True, exist_ok=True)
    
    # A converted box has NO `boxes/<box>/data/` -- conversion purges it -- so the
    # plain copy below would fail with "directory not found". Its DATA lives in the
    # repository, and the pointer says which snapshot is current.
    #
    # This restores into an ARBITRARY destination rather than a checkout, so it
    # deliberately writes no restic state record: that record means "this machine's
    # CHECKOUT is at snapshot X", and a copy taken somewhere else is not a checkout.
    _box_meta_for_format = BoxMeta.load(config, storage_location, box_index_name)
    if _box_meta_for_format.storage_format is StorageFormat.RESTIC:
        from boxyard._restic_sync import repo_for_box
        from boxyard._restic import (
            read_pointer,
            require_restic_available,
            pull as _restic_pull,
            restic_excludes_from_rclone_file,
        )
    
        require_restic_available(config, f"copy '{box_index_name}' from the remote")
    
        _pointer = await read_pointer(
            config.rclone_config_path, storage_location,
            sl_config.store_path, remote_index_name,
        )
        if _pointer is None:
            raise RuntimeError(
                f"Box '{box_index_name}' is a restic box with no data.snapshot "
                f"pointer, so there is no snapshot to copy. Finish the conversion "
                f"with `boxyard convert -r '{box_index_name}'` first."
            )
        _repo = repo_for_box(config, _box_meta_for_format, remote_index_name)
        if verbose:
            # Name the REPOSITORY and the snapshot, not `boxes/<box>/data`. That
            # directory was purged at conversion, so printing it sent anyone
            # debugging a failure to a path that cannot exist.
            print(
                f"Restoring DATA from {_repo.url} snapshot "
                f"{_pointer['snapshot'][:8]} to {dest_path}"
            )
        # The box's excludes ride along so the restore's `--delete` cannot touch
        # excluded content at the destination -- the copy usually lands in a fresh
        # directory, where this changes nothing, but copying over an existing tree
        # must honour the same "excluded content is local-only and untouched"
        # contract as every other restore. (That the full restore deletes
        # NON-excluded extraneous files at the destination, where the plain
        # branch's `rclone copy` never deletes anything, is a pre-existing
        # semantic difference recorded on ticket 43f05498.)
        await _restic_pull(
            _repo,
            dest_path,
            target_snapshot=_pointer["snapshot"],
            base_snapshot=None,
            excludes=restic_excludes_from_rclone_file(
                _box_meta_for_format.get_effective_exclude_path(config)
            ),
        )
    else:
        if verbose:
            print(f"Copying DATA from {storage_location}:{remote_data_path} to {dest_path}")
        success, stdout, stderr = await rclone_copy(
            rclone_config_path=config.rclone_config_path.as_posix(),
            source=storage_location,
            source_path=remote_data_path.as_posix(),
            dest="",
            dest_path=dest_path.as_posix(),
            progress=show_rclone_progress,
        )
    
        if not success:
            raise RuntimeError(f"Failed to copy DATA from remote: {stderr}")
    
    # Restore executable bits dropped by the transport (additive; no-op if no manifest).
    from boxyard._utils.perms import apply_exec_manifest
    
    apply_exec_manifest(dest_path)
    
    if verbose:
        print("DATA copied successfully.")
    if copy_meta:
        if verbose:
            print(f"Copying META from {storage_location}:{remote_meta_path}")
    
        dest_meta_path = dest_path / const.BOX_METAFILE_REL_PATH
        dest_meta_path.parent.mkdir(parents=True, exist_ok=True)
    
        success, stdout, stderr = await rclone_copyto(
            rclone_config_path=config.rclone_config_path.as_posix(),
            source=storage_location,
            source_path=remote_meta_path.as_posix(),
            dest="",
            dest_path=dest_meta_path.as_posix(),
            progress=show_rclone_progress,
        )
    
        if not success:
            if verbose:
                print(f"Warning: Failed to copy META: {stderr}")
        elif verbose:
            print("META copied successfully.")
    if copy_conf:
        if verbose:
            print(f"Copying CONF from {storage_location}:{remote_conf_path}")
    
        dest_conf_path = dest_path / const.BOX_CONF_REL_PATH
        dest_conf_path.mkdir(parents=True, exist_ok=True)
    
        success, stdout, stderr = await rclone_copy(
            rclone_config_path=config.rclone_config_path.as_posix(),
            source=storage_location,
            source_path=remote_conf_path.as_posix(),
            dest="",
            dest_path=dest_conf_path.as_posix(),
            progress=show_rclone_progress,
        )
    
        if not success:
            if verbose:
                print(f"Warning: Failed to copy CONF: {stderr}")
        elif verbose:
            print("CONF copied successfully.")
    return dest_path;
